import json
from collections import Counter
from dataclasses import dataclass
from datetime import datetime, timezone


@dataclass(frozen=True)
class Event:
    ts: datetime
    service: str
    level: str
    msg: str = ""


def parse_line(line):
    raw = json.loads(line)
    return Event(
        ts=datetime.fromisoformat(raw["ts"]),
        service=raw["service"],
        level=raw["level"],
        msg=raw.get("msg", ""),
    )


def read_events(path):
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                yield parse_line(line)


def as_utc(ts):
    # Naive timestamps are UTC by convention (see README).
    if ts.tzinfo is None:
        return ts.replace(tzinfo=timezone.utc)
    return ts.astimezone(timezone.utc)


def events_since(events, since):
    # `since` must be an aware datetime; events at or after it are kept.
    return (event for event in events if as_utc(event.ts) >= since)


def count_events(events):
    return Counter((event.service, event.level) for event in events)
