cat > evlog/cli.py <<'EOF'
import argparse
import sys
from datetime import date, datetime, timezone

from .events import count_events, events_since, read_events


def parse_since(value):
    try:
        day = date.fromisoformat(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid date {value!r}: expected YYYY-MM-DD, e.g. 2024-03-10")
    # Start of that day in UTC, matching how naive timestamps are read.
    return datetime(day.year, day.month, day.day, tzinfo=timezone.utc)


def build_parser():
    parser = argparse.ArgumentParser(prog="evlog")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="count events per service and level")
    report.add_argument("path", help="events file (JSON lines)")
    report.add_argument(
        "--since",
        type=parse_since,
        metavar="YYYY-MM-DD",
        help="only count events on or after this date (midnight UTC)",
    )
    return parser


def render(counts):
    lines = [f"{service} {level} {n}" for (service, level), n in sorted(counts.items())]
    lines.append(f"total {sum(counts.values())}")
    return "\n".join(lines)


def main(argv=None, out=None):
    out = out or sys.stdout
    args = build_parser().parse_args(argv)
    if args.command == "report":
        events = read_events(args.path)
        if args.since is not None:
            events = events_since(events, args.since)
        try:
            counts = count_events(events)
        except OSError as exc:
            print(f"evlog: cannot read {args.path}: {exc.strerror}", file=sys.stderr)
            return 1
        except (ValueError, KeyError) as exc:
            print(f"evlog: malformed event in {args.path}: {exc}", file=sys.stderr)
            return 1
        print(render(counts), file=out)
    return 0
